import { lineTotal, lineDiscount } from './invoices.js';
import { invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number ?? 'DRAFT');

  // Second line: customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;
  lines.push(customerName);

  // Line items
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    let lineText = `${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;

    // Add discount if non-zero
    if (line.discountPercent > 0) {
      const discount = lineDiscount(line);
      lineText += ` (${line.discountPercent}% off: -${formatEuros(discount)})`;
    }

    lines.push(lineText);
  }

  // Totals
  const totals = invoiceTotals(invoice);
  if (totals.discount > 0) {
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}

