});

test('addLine does not mutate original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const original = JSON.parse(JSON.stringify(invoice));

  addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.deepEqual(invoice, original);
});

test('removeLine removes a line by SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  }).value;

  const r = removeLine(invoice, 'DEV-HOUR');

  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[1].sku, 'COPY-HOUR');
});

