  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;
  invoice.status = 'paid';

