test('renderInvoiceText shows VAT line for items with VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);

  assert.ok(text.includes('VAT: +€178.50'));
});

test('renderInvoiceText shows VAT before total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  const vatLine = lines.findIndex(l => l.startsWith('VAT:'));
  const totalLine = lines.findIndex(l => l.startsWith('Total:'));

  assert.ok(vatLine !== -1);
  assert.ok(totalLine !== -1);
  assert.ok(vatLine < totalLine);
});

test('renderInvoiceText does not show VAT line for zero VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-06-15',
