    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice reports an unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-06-15',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  const original = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines,
  });

  assert.deepEqual(lines, original);
});

test('createInvoice handles different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 9);
  assert.equal(r.value.lines[1].vatRate, 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal returns zero for zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 8500 }), 0);
});

test('invoiceTotals sums line totals and includes VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const expectedSubtotal = 10 * 8500 + 5 * 9500;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 27825);
  assert.equal(totals.total, expectedSubtotal + 27825);
});

test('invoiceTotals handles single line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 3 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 360000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 75600);
  assert.equal(totals.total, 360000 + 75600);
});

test('invoiceTotals works with mixed prices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'STICKER', qty: 1000 },
      { sku: 'ICON-SET', qty: 5 },
      { sku: 'BRAND-BOOK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const expectedSubtotal = 1000 * 50 + 5 * 980 + 1 * 245000;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 62979);
  assert.equal(totals.total, expectedSubtotal + 62979);
});

test('addLine adds a new line at the end', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[1].qty, 5);
  assert.equal(r.value.lines[1].name, 'Development (hour)');
  assert.equal(r.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty for existing SKU', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;

  const r = addLine(invoice, { sku: 'DES-HOUR', qty: 5 });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].qty, 15);
});

test('addLine reports NOT_DRAFT for non-draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  }).value;
