test('invoiceTotals includes discount and VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-06-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 10 * 8500 + 5 * 9500);
  assert.equal(totals.discount, 8500 + 9500);
  assert.equal(totals.vat, 22680);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

